+static unsigned long syz_rg_frees;
+static unsigned long syz_rg_free_next = 1;
+
 static int ntfs_fs_reconfigure(struct fs_context *fc)
 {
 	struct super_block *sb = fc->root->d_sb;
@@ -461,6 +466,12 @@ static int ntfs_fs_reconfigure(struct fs_context *fc)
 	}
 
 	sync_filesystem(sb);
+	if (!strncmp(current->comm, "syzrepro8", 10)) {
+		syz_rg_swaps++;
+		if (syz_rg_swaps == syz_rg_swap_next) {
+			syz_rg_swap_next = syz_rg_swaps + 400;
+		}
+	}
 	swap(sbi->options, fc->fs_private);
 
 	return 0;
@@ -1835,6 +1846,12 @@ static void ntfs_fs_free(struct fs_context *fc)
 		ntfs3_free_sbi(sbi);
