static void pin_cpu(int cpu)
{
	cpu_set_t s;
	CPU_ZERO(&s);
	CPU_SET(cpu, &s);
	sched_setaffinity(0, sizeof(s), &s);
}

static void *reader_fn(void *arg)
{
	unsigned char fa[64];
	unsigned long n = 0;

	(void)arg;
	prctl(PR_SET_NAME, "syzrepro0", 0, 0, 0);
	pin_cpu(1);
	while (!g_stop) {
		int fd = g_dirfd;
		if (fd < 0) {
			sched_yield();
			continue;
		}

		syscall(__NR_file_getattr, fd, (void *)0, fa, (size_t)24,
			AT_EMPTY_PATH);
		g_reads = ++n;
	}
	return NULL;
}

static void *cycler_fn(void *arg)
{
	unsigned long cyc = 0;

	(void)arg;
	prctl(PR_SET_NAME, "syzrepro8", 0, 0, 0);
	pin_cpu(2);
	while (!g_stop) {
		int fd, r, tries;

		if (mount(g_loopname, MNT_PATH, "ntfs3", g_mflags, g_mopts) != 0) {
			g_mount_errno = errno;
			g_mount_err++;
			usleep(2000);
			continue;
		}
		g_mount_ok++;
		fd = open(MNT_PATH, O_RDONLY | O_DIRECTORY);
		if (fd < 0) {
			umount2(MNT_PATH, MNT_DETACH);
			usleep(2000);
			continue;
		}

		g_dirfd = fd;
		usleep(3000);

		r = mount(NULL, MNT_PATH, NULL, MS_REMOUNT | (g_mflags & MS_RDONLY),
			  NULL);
		if (r == 0)
			g_remount_ok++;
		else {
			g_remount_errno = errno;
			g_remount_err++;
		}

		usleep(2500);

		g_dirfd = -1;
		usleep(300);
		close(fd);
		for (tries = 0; tries < 200; tries++) {
			if (umount2(MNT_PATH, 0) == 0)
				break;
			if (errno != EBUSY) {
				umount2(MNT_PATH, MNT_DETACH);
				break;
			}
			usleep(500);
		}
		g_cycles = ++cyc;
	}
	return NULL;
}

static void *ipi_fn(void *arg)
{
	unsigned long s = 0x9e3779b97f4a7c15UL;

	(void)arg;
	prctl(PR_SET_NAME, "syzrepro9", 0, 0, 0);
	pin_cpu(0);
	while (!g_stop) {
		syscall(__NR_membarrier, MB_CMD_PRIVATE_EXPEDITED, 0, 0);
		g_ipis++;

		s = s * 6364136223846793005UL + 1442695040888963407UL;
		{
			volatile unsigned long k = (s >> 54) & 0x7ff;
			while (k)
				k--;
