	return NULL;
}

static int setup_loop(void)
{
	unsigned char *img;
	int fd, lfd, ffd, n = -1;
	ssize_t wr;

	img = build_image();
	if (!img)
		return -1;
	fd = open(IMG_PATH, O_RDWR | O_CREAT | O_TRUNC, 0600);
	if (fd < 0) {
		return -1;
	}
	wr = write(fd, img, IMG_RAW_SIZE);
	if (wr != (ssize_t)IMG_RAW_SIZE) {
		close(fd);
		return -1;
	}
	fsync(fd);
	close(fd);
	free(img);

	fd = open("/dev/loop-control", O_RDWR);
	if (fd >= 0) {
		n = ioctl(fd, LOOP_CTL_GET_FREE, 0);
		close(fd);
	}
	if (n < 0)
		n = 0;
	snprintf(g_loopname, sizeof(g_loopname), "/dev/loop%d", n);

	lfd = open(g_loopname, O_RDWR);
	if (lfd < 0) {
		return -1;
	}
	ffd = open(IMG_PATH, O_RDWR);
	if (ffd < 0) {
		close(lfd);
		return -1;
	}
	if (ioctl(lfd, LOOP_SET_FD, ffd) < 0) {
		close(ffd);
		close(lfd);
		return -1;
	}

	close(ffd);
	close(lfd);
	return 0;
}

