+	// TODO: Wait here for completion of prev subreq
+
+	stream->issue_from += subreq->len;
+	stream->buffered   -= subreq->len;
+	if (stream->buffered == 0)
+		netfs_all_subreqs_queued(subreq->rreq);
+	return 0;
+}
